//! Non-secret desktop preferences, read from `$XDG_CONFIG_HOME/pigeon/settings.json`.
//!
//! The file may be generated by the Home Manager module, in which case it is a
//! symlink into the read-only Nix store. The app then treats it as managed and
//! never rewrites it. Secrets never belong here; they live in the keyring.

use std::io::Write;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

pub const FILE_NAME: &str = "settings.json";

/// What a new-mail notification may reveal. Message bodies are never shown.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum NotificationPolicy {
    #[default]
    SenderSubject,
    Count,
    Off,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct DesktopSettings {
    /// Closing the main window hides it and keeps syncing; Quit still exits.
    pub close_to_background: bool,
    pub notifications: NotificationPolicy,
    /// Show a status-area icon when a tray host is present. Nothing depends on it.
    pub tray: bool,
    /// Look up website icons for senders. This tells an outside service which
    /// domains email the user, so it stays off until they choose it.
    pub sender_images: bool,
}

impl Default for DesktopSettings {
    fn default() -> Self {
        Self {
            close_to_background: true,
            notifications: NotificationPolicy::default(),
            tray: false,
            sender_images: false,
        }
    }
}

/// Settings as loaded, with where they came from.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct LoadedSettings {
    pub settings: DesktopSettings,
    /// Generated outside the app (Home Manager); edits are refused.
    pub managed: bool,
    /// Why the file could not be used. Defaults apply and the file is left alone.
    pub warning: Option<String>,
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum SettingsError {
    #[error("these settings are managed by Home Manager; change them in your Nix configuration")]
    Managed,
    #[error("the settings file is unreadable; fix or remove it first")]
    Invalid,
    #[error("could not save settings: {0}")]
    Io(String),
}

pub fn settings_path(config_dir: &Path) -> PathBuf {
    config_dir.join("pigeon").join(FILE_NAME)
}

/// A store symlink or a read-only file means something else owns the settings.
pub fn is_managed(path: &Path) -> bool {
    match std::fs::symlink_metadata(path) {
        Ok(meta) if meta.file_type().is_symlink() => true,
        Ok(meta) => meta.permissions().readonly(),
        Err(_) => false,
    }
}

pub fn load(path: &Path) -> LoadedSettings {
    let managed = is_managed(path);
    let (settings, warning) = match std::fs::read_to_string(path) {
        Ok(text) => match serde_json::from_str::<DesktopSettings>(&text) {
            Ok(settings) => (settings, None),
            Err(error) => (
                DesktopSettings::default(),
                Some(format!(
                    "{} is not valid ({error}); using defaults",
                    path.display()
                )),
            ),
        },
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            (DesktopSettings::default(), None)
        }
        Err(error) => (
            DesktopSettings::default(),
            Some(format!(
                "{} could not be read ({error}); using defaults",
                path.display()
            )),
        ),
    };
    LoadedSettings {
        settings,
        managed,
        warning,
    }
}

/// Saves through a temporary file and rename, so a crash never leaves half a file.
pub fn save(path: &Path, settings: &DesktopSettings) -> Result<LoadedSettings, SettingsError> {
    let current = load(path);
    if current.managed {
        return Err(SettingsError::Managed);
    }
    // Never replace a file the user wrote by hand but got wrong.
    if current.warning.is_some() && path.exists() {
        return Err(SettingsError::Invalid);
    }
    let io = |error: std::io::Error| SettingsError::Io(error.to_string());
    let dir = path.parent().ok_or(SettingsError::Io("no parent".into()))?;
    std::fs::create_dir_all(dir).map_err(io)?;
    let temporary = dir.join(format!(".{FILE_NAME}.tmp"));
    let mut file = std::fs::File::create(&temporary).map_err(io)?;
    let mut text =
        serde_json::to_string_pretty(settings).map_err(|e| SettingsError::Io(e.to_string()))?;
    text.push('\n');
    file.write_all(text.as_bytes()).map_err(io)?;
    file.sync_all().map_err(io)?;
    std::fs::rename(&temporary, path).map_err(io)?;
    Ok(LoadedSettings {
        settings: settings.clone(),
        managed: false,
        warning: None,
    })
}
